package org.apache.commons.lang3.math;

import java.io.*;
import java.lang.reflect.Array;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen1Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, n.intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        Number n = NumberUtils.createNumber("12345678901");
        assertTrue(n instanceof Long);
        assertEquals(12345678901L, n.longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        Number n = NumberUtils.createNumber("12345678901234567890");
        assertTrue(n instanceof BigInteger);
        assertEquals(new BigInteger("12345678901234567890"), n);
    }

    @Test
    public void testCreateNumber_Float() {
        Number n = NumberUtils.createNumber("1.23");
        assertTrue(n instanceof Float);
        assertEquals(1.23f, n.floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_Double() {
        Number n = NumberUtils.createNumber("1.234567890123");
        assertTrue(n instanceof Double);
        assertEquals(1.234567890123, n.doubleValue(), 0.000000000001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        Number n = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(n instanceof BigDecimal);
        assertEquals(new BigDecimal("1.234567890123456789"), n);
    }

    @Test
    public void testCreateNumber_HexInteger() {
        Number n = NumberUtils.createNumber("0x7FFFFFFF");
        assertTrue(n instanceof Integer);
        assertEquals(Integer.MAX_VALUE, n.intValue());
    }

    @Test
    public void testCreateNumber_HexLong() {
        Number n = NumberUtils.createNumber("0x7FFFFFFFFFFFFFFF");
        assertTrue(n instanceof Long);
        assertEquals(Long.MAX_VALUE, n.longValue());
    }

    @Test
    public void testCreateNumber_HexBigInteger() {
        Number n = NumberUtils.createNumber("0x7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_HexPrefixes() {
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0x0A").intValue());
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0X0A").intValue());
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("#0A").intValue());
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("-#0A").intValue());
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("-0x0A").intValue());
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("-0X0A").intValue());
        // Test leading zeros in hex
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0x0000000A").intValue());
    }

    @Test
    public void testCreateNumber_SuffixL() {
        Number n = NumberUtils.createNumber("123L");
        assertTrue(n instanceof Long);
        assertEquals(123L, n.longValue());

        Number bn = NumberUtils.createNumber("12345678901234567890L");
        assertTrue(bn instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_SuffixF() {
        Number n = NumberUtils.createNumber("1.23f");
        assertTrue(n instanceof Float);
    }

    @Test
    public void testCreateNumber_SuffixD() {
        Number n = NumberUtils.createNumber("1.23d");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_Exponent() {
        Number n = NumberUtils.createNumber("1.23e2");
        assertEquals(123.0, n.doubleValue(), 0.001);

        Number n2 = NumberUtils.createNumber("1.23E2");
        assertEquals(123.0, n2.doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_InvalidSuffix() {
        try {
            NumberUtils.createNumber("123z");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("not a valid number"));
        }
    }

    @Test
    public void testCreateNumber_InvalidExponent() {
        try {
            NumberUtils.createNumber("1.23e");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumber_EdgeCases() {
        // Test all zeros logic
        Number n = NumberUtils.createNumber("0.00000000000000000000");
        assertTrue(n instanceof BigDecimal);

        // Test large hex with specific digit threshold
        // 16 hex digits, first is '8' -> should be Long or BigInt depending on implementation logic
        Number nHex = NumberUtils.createNumber("0x8000000000000000");
        assertTrue(nHex instanceof Long || nHex instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_FloatPrecisionLoss() {
        // Very long decimal should fall back to Double or BigDecimal
        Number n = NumberUtils.createNumber("1.1234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }
}
